def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Determine the starting point
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    # Track number of links followed
    link_count = 0

    # Process each component
    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = ''  # Already at root
            else:
                # Remove the last component
                parts = current.rstrip('/').split('/')
                if len(parts) > 1:
                    current = '/'.join(parts[:-1])
                else:
                    current = ''
            i += 1
            continue

        # Append the component
        if current == '':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the target
            target = links[candidate]

            # Resolve the target
            # The remaining components after current one
            remaining = components[i+1:]

            # If target is absolute, start from root
            if target.startswith('/'):
                # Parse target and append remaining components
                new_path = target
                if remaining:
                    new_path = target + '/' + '/'.join(remaining)
            else:
                # Target is relative to the directory containing the link
                # The directory containing the link is the parent of candidate
                if current == '':
                    link_dir = ''
                else:
                    parts = current.rstrip('/').split('/')
                    if len(parts) > 1:
                        link_dir = '/'.join(parts[:-1])
                    else:
                        link_dir = ''

                # Build the new path
                if link_dir == '':
                    new_path = target
                else:
                    new_path = link_dir + '/' + target

                if remaining:
                    new_path = new_path + '/' + '/'.join(remaining)

            # Recursively resolve the new path with remaining link budget
            # We need to continue from where we are with link_count already used
            remaining_links = 8 - link_count
            result = resolve_with_budget(new_path, '', links, remaining_links)
            if result is None:
                return None
            return result

        # Not a symlink, update current
        current = candidate
        i += 1

    # Normalize the result
    if current == '':
        return '/'
    else:
        return current.rstrip('/')

